let ownerMeetingBusy=false,ownerYouthIdentity='';
function renderOwnerBoard(){
 if(view!=='club')return;const host=$('owner-board-panel');if(!host)return;
 const model=OwnerBoard.read(season),esc=escapeText,open=host.querySelector('details')?.open||false;
 if(!model.youth.some(p=>p.identity===ownerYouthIdentity))ownerYouthIdentity=model.youth[0]?.identity||'';
 const active=model.active,name=active?.identity?F.identityProfile(active.identity)?.name:'',confidence=model.confidence||{score:model.trust,status:model.relationship,rank:null,target:2,played:0},confidenceNote=confidence.rank?`현재 ${confidence.rank}위 · 목표 ${confidence.target}위 이내 · ${confidence.played}경기`:`리그 결과 반영 대기 · 목표 ${confidence.target}위 이내`,confidenceTone=confidence.score<35?'critical':confidence.score<50?'warning':'stable',labels={fulfilled:'약속 달성',missed:'약속 미달성',pending:'진행 중',reported:'선수 보호 보고',invested:'투자 승인'};
 host.innerHTML=`<section class="owner-board-card" aria-labelledby="owner-board-title"><header class="owner-board-heading"><div><span class="eyebrow">THE BOARDROOM</span><h2 id="owner-board-title">구단주 면담</h2></div><span class="owner-trust">신뢰 <b>${model.trust}</b> / 100</span></header><div class="owner-confidence" data-confidence="${confidenceTone}"><div><strong>이사회 신임도</strong><b>${esc(confidence.status)} · ${confidence.score}</b></div><progress max="100" value="${confidence.score}" aria-label="이사회 신임도 ${confidence.score} / 100"></progress><small>${confidenceNote}</small></div><p>${esc(model.relationship)} · 투자는 신뢰 60부터</p>${active?`<div class="owner-promise"><strong>${esc(active.label)}${name?' · '+esc(name):''}</strong><span>${active.year}시즌 ${active.end}R 결과 확정까지 · ${active.progress} / ${active.target}${active.unit}</span><progress max="${active.target}" value="${Math.min(active.progress,active.target)}" aria-label="약속 진행 ${active.progress} / ${active.target}${active.unit}"></progress><small>컵·유럽 경기 제외 · 기한까지 확인한 뒤 신뢰 반영</small></div>`:'<p class="owner-promise-empty">진행 중인 약속이 없습니다. 구단의 다음 방향을 이야기해 보세요.</p>'}<details${open?' open':''}><summary>면담 주제와 최근 기록</summary><p class="owner-rules">리그 준비 주간에 한 번 · 주제를 누르면 면담이 확정됩니다. 약속 중에는 선수 보호 보고만 가능합니다.</p>${model.youth.length?`<label class="owner-youth-label" for="owner-youth-player">출전 기회를 약속할 유소년<select id="owner-youth-player">${model.youth.map(p=>`<option value="${esc(p.identity)}"${p.identity===ownerYouthIdentity?' selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:''}<div class="owner-choices">${model.options.map(o=>`<button type="button" data-owner-choice="${o.id}"${!o.available||ownerMeetingBusy?' disabled':''}><strong>${esc(o.label)}</strong><span>${esc(o.description)}</span>${o.reason?'<small>'+esc(o.reason)+'</small>':''}</button>`).join('')}</div>${model.recent.length?`<ol class="owner-history">${model.recent.map(r=>`<li><strong>${r.year}시즌 ${r.round}R · ${esc(r.label)}</strong><span>${labels[r.status]}${r.status==='fulfilled'||r.status==='missed'?' · '+r.progress+' / '+r.target+r.unit:''} · ${r.status==='pending'?'평가 대기':'신뢰 변화 '+(r.delta>0?'+':'')+r.delta}${r.status==='invested'?' · £20,000 입금':''}</span></li>`).join('')}</ol>`:'<p class="owner-rules">첫 면담부터 기록합니다. 기존 저장의 과거 약속은 만들지 않습니다.</p>'}<p class="owner-rules">약속은 최대 리그 3경기, 시즌 말에는 남은 경기 수에 맞춰 줄어듭니다. 투자 내역은 재정 장부에 남고 신뢰와 면담 기록은 다음 시즌에도 이어집니다.</p></details><p class="owner-status" role="status">${model.reason?esc(model.reason):'면담 가능 · 감독의 선택을 기다립니다.'}</p></section>`;
 const select=$('owner-youth-player');if(select)select.onchange=()=>{ownerYouthIdentity=select.value;};
 host.querySelectorAll('[data-owner-choice]').forEach(button=>button.onclick=()=>{
  if(ownerMeetingBusy||button.disabled)return;ownerMeetingBusy=true;button.disabled=true;
  try{action(()=>{season=OwnerBoard.meet(season,button.dataset.ownerChoice,ownerYouthIdentity);state=season.match;});}
  finally{ownerMeetingBusy=false;renderOwnerBoard();host.querySelector('summary')?.focus({preventScroll:true});}
 });
}
